<p class="fine" data-continuation-copy-status role="status"></p><?php if(!empty($issuedLink)):?><details data-continuation-manual><summary>Copy continuation message manually</summary><label>One short message to send to your AI<textarea id="continuation-start-message" readonly rows="6"><?=e(sr_start_message($continuation))?></textarea></label></details><?php endif ?>
